CREATE OR REPLACE FUNCTION public.pos_cancel_cloud_sale_apply_fase6e(p_license_key text, p_device_fingerprint text, p_security_token text DEFAULT NULL::text, p_staff_session_token text DEFAULT NULL::text, p_sale_id text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_staff_user_id uuid;
  v_sale_staff_user_id uuid;
  v_sale_found boolean := false;
begin
  v_context := private.validate_pos_sync_context(
    p_license_key,
    p_device_fingerprint,
    p_security_token,
    p_staff_session_token
  );
  perform private.assert_cloud_sales_cancellations_enabled(v_context);
  perform private.assert_pos_permission(v_context, 'pos');
  perform private.assert_pos_permission(v_context, 'refunds');

  v_license_id := (v_context->>'license_id')::uuid;
  v_staff_user_id := nullif(v_context->>'staff_user_id', '')::uuid;

  select true, s.staff_user_id
  into v_sale_found, v_sale_staff_user_id
  from public.pos_sales s
  where s.license_id = v_license_id
    and s.id = nullif(btrim(coalesce(p_sale_id, '')), '')
  limit 1;

  if coalesce(v_context->>'actor_type', v_context->>'device_role', 'staff') = 'staff'
     and v_sale_found
     and v_sale_staff_user_id is distinct from v_staff_user_id
     and not private.has_pos_permission(v_context, 'sales_cancellations_global') then
    raise exception 'SALE_CANCELLATION_FORBIDDEN' using errcode = 'P0001';
  end if;

  return public.pos_cancel_cloud_sale_apply_fase6e_legacy_r1(
    p_license_key,
    p_device_fingerprint,
    p_security_token,
    p_staff_session_token,
    p_sale_id,
    p_reason,
    p_idempotency_key
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.validate_customer_payment_allocations(p_allocations jsonb, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_item jsonb;
  v_total numeric := 0;
  v_amount numeric;
  v_result jsonb := '[]'::jsonb;
begin
  if p_allocations is null then
    return '[]'::jsonb;
  end if;

  if jsonb_typeof(p_allocations) <> 'array' then
    raise exception 'CUSTOMER_PAYMENT_ALLOCATIONS_INVALID' using errcode = 'P0001';
  end if;

  for v_item in select value from jsonb_array_elements(p_allocations)
  loop
    v_amount := coalesce((v_item->>'amount_applied')::numeric, (v_item->>'amountApplied')::numeric, 0);
    if v_amount < 0 then
      raise exception 'CUSTOMER_PAYMENT_ALLOCATION_NEGATIVE' using errcode = 'P0001';
    end if;
    if v_amount > 0 then
      v_total := v_total + v_amount;
      v_result := v_result || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
        'sale_id', coalesce(v_item->>'sale_id', v_item->>'saleId'),
        'amount_applied', v_amount,
        'previous_sale_balance', nullif(coalesce(v_item->>'previous_sale_balance', v_item->>'previousSaleBalance'), '')::numeric,
        'new_sale_balance', nullif(coalesce(v_item->>'new_sale_balance', v_item->>'newSaleBalance'), '')::numeric,
        'metadata', coalesce(v_item->'metadata', '{}'::jsonb)
      )));
    end if;
  end loop;

  if v_total > p_amount then
    raise exception 'CUSTOMER_PAYMENT_ALLOCATIONS_EXCEED_AMOUNT' using errcode = 'P0001';
  end if;

  return v_result;
end;
$function$
